using System.Text.Json;
using System.Text.Json.Serialization;

namespace CollectionsDB.Models;

public class Card
{
    private string _id = Guid.NewGuid().ToString();

    // Generated by the app (like collections). A null/empty id coming from the
    // client gets a fresh Guid instead of crashing the insert.
    public string Id
    {
        get => _id;
        set => _id = string.IsNullOrWhiteSpace(value) ? Guid.NewGuid().ToString() : value;
    }

    // FK to collections. Set by the service, not required from the client.
    public string CollectionId { get; set; } = "";

    public string Key { get; set; } = null!;

    // EF can't map "object". JsonElement maps to a jsonb column and still
    // accepts whatever shape the Angular app sends (string, bool, array, ...).
    public JsonElement? Value { get; set; }

    public CardType CardType { get; set; }

    public bool IsFavorite { get; set; } = false;

    public bool IsArchived { get; set; } = false;

    public int Position { get; set; } = -1;

    // Input only: the controller sets it, the service saves it into
    // card_embeddings. Not a column on cards and never sent to the client.
    [JsonIgnore]
    public List<float>? Embedding { get; set; }

    // Text that gets embedded. Deliberately excludes Id so the random Guid
    // doesn't pollute the vector.
    public string ToEmbeddingText() => $"{Key}: {Value}";

    public override string ToString() => $"Card(Id={Id}, Key={Key}, Value={Value})";
}

public enum CardType
{
    SUBJECT,
    STORY,
    KEY_VALUE,
    CHECKBOX,
    LINK,
    IMAGE
}
